approved_command_prefixes:
$root=(Resolve-Path .).Path
$target=Join-Path $root '.pytest-tmp-main-check'
if (Test-Path -LiteralPath $target) {
  $resolved=(Resolve-Path -LiteralPath $target).Path
  if (-not $resolved.StartsWith($root)) { throw "Refusing to delete outside workspace: $resolved" }
  Remove-Item -LiteralPath $resolved -Recurse -Force
}
git status --short --untracked-files=all

$root=(Resolve-Path .).Path
Get-ChildItem -Force -Directory | Where-Object { $_.Name -like '.pytest-tmp-pr-g-*' } | ForEach-Object {
  $resolved=$_.FullName
  if ($resolved.StartsWith($root)) { Remove-Item -LiteralPath $resolved -Recurse -Force }
}
git status --short --untracked-files=all
git diff --stat

